from 写入第二遍 import add
add('19_002',1.5,'16:9，从青背后低位仰拍全景，青肩背在画面右下近侧，武士巨大躯体从左上方逼近；镜头随青抬头上摇，落幅保留两人间骤然缩短的天空空隙。','青听见破风便把头抬起，脸侧手掌离开耳边，肩背向后收；武士已腾在她近上方，粗壮手臂沿来势朝她胸前扫进，身体紧跟手臂下压，破衣角向后拖开。青的马尾先向侧后方甩出，身体准备从攻击线退开。','铅蓝云天与少量米灰碎屑填在两人之间，下缘仅余薄尘。','上方云天冷白漫射，庞大躯体下侧较暗，空地反光给青肩侧弱中性补光。','骤近的低沉破风盖住落灰细响，青短促吸气。',phase='process',node={'武士.阶段':'腾空近身手臂扫入','青.阶段':'抬头后收肩避让'},meaning='武士从尘雾侧跃到青近上方，向她胸前扫臂；低仰观察与近大远小关系保留。')
add('19_003',5,'16:9，青的侧面胸上近景位于画面右侧，粗壮手臂沿左侧近处横扫，脸、衣物外轮廓与手臂之间的窄空隙同时可见；镜头随她后仰向后退，落幅仍读出两者分开。','青把胸肩和头一起向后撤，腰身折开；武士粗壮手臂擦着她胸前通过，手臂与衣物之间留下窄窄空隙，衣襟只是被气流向后压。她睁大眼、露齿惊叫，近处发束猛然甩过脸侧；来袭腕部越过她身前时，她把右手从肋旁迎上去，指尖已对准腕部收束处。','左侧薄米灰尘与窄条浅冷灰天空被同向速度线拉长，人物与手臂间只有短促的浅色空隙。','上方云天冷白柔光，近处手臂经过时局部短暂遮光，立即恢复。','只是一记紧擦身前的长破风，衣料被风压拍响，青急吸气；手部握紧声接向下一镜。',ja=['うわっ！','本当に、また起き上がってきた！'],tone='第一声被突袭逼出，后句惊讶急喊，身体始终在躲闪接招。',kind='mixed',phase='process',node={'青.阶段':'后仰躲过扫臂、右手迎向腕部','青.新伤':'此击没有命中','双方.接触':'尚未抓实'},meaning='按用户明确解释：手臂擦胸而过，没有击中青；尖白形是近擦速度重音，不画成打击或新伤。',card={'opening':'青刚抬头就迎上逼近手臂。','beats':['胸肩后撤、露齿惊叫，衣物与来臂始终分开','手臂掠过后，右手迎向腕部'],'coupling':'躲开与准备抓腕是同一股动作，不先挨打再复原。','landing':'攻击已越过，指端将接住腕部。'})
add('20_001a',1,'16:9，青的手与武士腕部极近景，粗壮手臂由画面左下斜贯右上，手指从上方扣入；固定机位。','青右手指尖先搭住掠过的腕部收束处，四指随即扣紧，掌根贴实；武士手臂仍向前走，青的手腕被带出一小段后稳住，抓握处的肌理压出细褶。','画面余隙仅有浅冷灰天空背景与一层淡米灰尘。','上方冷白天光照到指背，接触处柔暗，腕部高光随运动滑过。','短促抓握闷响与指端擦声，来臂破风被握紧的顿挫截短。',phase='contact',node={'双方.接触':'青右手已扣住武士右腕','青.阶段':'抓腕受力'},meaning='原格实际抓握节点落实；右手抓武士右腕是统一动作设计，不伪称原裁切单独证实手别。')
